import sys
events = []
class Out:
    def write(self, text):
        events.append('write')
        if 'write' == 'write': raise ValueError('stream failed')
        return len(text)
    def flush(self):
        events.append('flush')
        if 'write' == 'flush': raise ValueError('stream failed')
class In:
    def readline(self):
        events.append('read')
        if 'write' == 'read': raise ValueError('stream failed')
        return 'answer\n'
oldin, oldout = sys.stdin, sys.stdout
try:
    sys.stdin, sys.stdout = In(), Out()
    try: result = ('ok', input('prompt'))
    except BaseException as error: result = ('exception', type(error).__name__, error.args)
finally:
    sys.stdin, sys.stdout = oldin, oldout
print(repr((result, events)))

